package site.hsu.hub.recruitment.adapter.in.web;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import site.hsu.hub.common.api.*;import site.hsu.hub.recruitment.api.*;
@RestController@RequestMapping("/api/v1/recruitments")public class RecruitmentController implements RecruitmentControllerDocs{private final RecruitmentApplicationReader service;public RecruitmentController(RecruitmentApplicationReader service){this.service=service;}@Override@GetMapping("/{id}/form")public ApiResponse<FormDefinition>form(@PathVariable Long id,HttpServletRequest req){return Responses.ok(service.form(id),req);}}
